package org.sonar.python.checks.hotspots;

import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.symbols.Symbol;
import org.sonar.plugins.python.api.tree.Argument;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.HasSymbol;
import org.sonar.plugins.python.api.tree.Name;
import org.sonar.plugins.python.api.tree.QualifiedExpression;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.StringLiteral;
import org.sonar.plugins.python.api.tree.Tree.Kind;
import org.sonar.python.checks.hotspots.CommonValidationUtils.ArgumentValidator;
import org.sonar.python.checks.hotspots.CommonValidationUtils.CallValidator;
import org.sonar.python.checks.utils.Expressions;
import org.sonar.python.tree.TreeUtils;

import static org.sonar.python.semantic.SymbolUtils.qualifiedNameOrEmpty;

@Rule(key = "S4426")
public class StrongCryptographicKeysCheck extends PythonSubscriptionCheck {
  public static final String MESSAGE_AT_LEAST_65537_EXPONENT = "Use a public key exponent of at least 65537.";
  public static final String MESSAGE_AT_LEAST_2048_BIT = "Use a key length of at least 2048 bits.";
  public static final String MESSAGE_AT_LEAST_224_BIT = "Use a key length of at least 224 bits.";
  public static final String MESSAGE_NIST_APPROVED_CURVE = "Use a NIST-approved elliptic curve.";
  public static final String CURVE = "curve";
  private static final Pattern CRYPTOGRAPHY_FORBIDDEN_CURVE = Pattern.compile("(SECP192R1|SECT571K1|SECT409K1|SECT283K1|SECT233K1|SECT163K1|SECT571R1|SECT409R1|SECT283R1|SECT233R1|SECT163R2)");
  private static final ArgumentValidator CRYPTOGRAPHY_KEY_SIZE = new ArgumentValidator(
    1, "key_size", (ctx, argument) -> {
    if (isLessThan2048(argument)) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_2048_BIT);
    }
  });

  private static final ArgumentValidator CRYPTOGRAPHY_PUBLIC_EXPONENT = new ArgumentValidator(
    0, "public_exponent", (ctx, argument) -> {
    if (isLessThan65537(argument)) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_65537_EXPONENT);
    }
  });

  private static final ArgumentValidator CRYPTOGRAPHY_CURVE = new ArgumentValidator(
    0, CURVE, (ctx, argument) -> {
    if (isNonCompliantCurve(argument.expression())) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_224_BIT);
    }
  });

  private static final ArgumentValidator CRYPTO_CRYPTODOME_KEY_SIZE = new ArgumentValidator(
    0, "bits", (ctx, argument) -> {
    if (isLessThan2048(argument)) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_2048_BIT);
    }
  });

  private static final ArgumentValidator CRYPTO_EXPONENT = new ArgumentValidator(
    3, "e", (ctx, argument) -> {
    if (isLessThan65537(argument)) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_65537_EXPONENT);
    }
  });

  private static final ArgumentValidator CRYPTODOME_EXPONENT = new ArgumentValidator(
    2, "e", (ctx, argument) -> {
    if (isLessThan65537(argument)) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_65537_EXPONENT);
    }
  });

  private static final ArgumentValidator CRYPTODOME_ELGAMAL_CURVE = new ArgumentValidator(
    0, CURVE, (ctx, argument) -> {
    if (isLessThan2048(argument)) {
      ctx.addIssue(argument, MESSAGE_AT_LEAST_2048_BIT);
    }
  });

  private static final ArgumentValidator CRYPTODOME_ECC_FORBIDDEN_CURVE = new ArgumentValidator(
    0, CURVE, (ctx, argument) -> {
    if (isForbiddenCurve(argument.expression(), Set.of("NIST P-192", "p192", "P-192", "prime192v1", "secp192r1"))) {
      ctx.addIssue(argument, MESSAGE_NIST_APPROVED_CURVE);
    }
  });

  private static final Map<String, Collection<CallValidator>> CALL_EXPRESSION_VALIDATORS =
    Map.ofEntries(
      Map.entry("cryptography.hazmat.primitives.asymmetric.rsa.generate_private_key", List.of(CRYPTOGRAPHY_KEY_SIZE, CRYPTOGRAPHY_PUBLIC_EXPONENT, CRYPTOGRAPHY_CURVE)),
      Map.entry("cryptography.hazmat.primitives.asymmetric.dsa.generate_private_key", List.of(CRYPTOGRAPHY_KEY_SIZE, CRYPTOGRAPHY_PUBLIC_EXPONENT, CRYPTOGRAPHY_CURVE)),
      Map.entry("cryptography.hazmat.primitives.asymmetric.ec.generate_private_key", List.of(CRYPTOGRAPHY_KEY_SIZE, CRYPTOGRAPHY_PUBLIC_EXPONENT, CRYPTOGRAPHY_CURVE)),
      Map.entry("cryptography.hazmat.primitives.asymmetric.dh.generate_parameters", List.of(CRYPTOGRAPHY_KEY_SIZE)),
      Map.entry("Crypto.PublicKey.RSA.generate", List.of(CRYPTO_CRYPTODOME_KEY_SIZE, CRYPTO_EXPONENT)),
      Map.entry("Crypto.PublicKey.DSA.generate", List.of(CRYPTO_CRYPTODOME_KEY_SIZE, CRYPTO_EXPONENT)),
      Map.entry("Cryptodome.PublicKey.RSA.generate", List.of(CRYPTO_CRYPTODOME_KEY_SIZE, CRYPTODOME_EXPONENT)),
      Map.entry("Cryptodome.PublicKey.DSA.generate", List.of(CRYPTO_CRYPTODOME_KEY_SIZE, CRYPTODOME_EXPONENT)),
      Map.entry("Cryptodome.PublicKey.ElGamal.generate", List.of(CRYPTODOME_ELGAMAL_CURVE)),
      Map.entry("Cryptodome.PublicKey.ECC.generate", List.of(CRYPTODOME_ECC_FORBIDDEN_CURVE)),
      Map.entry("OpenSSL.crypto.PKey.generate_key", List.of(new OpenSslCryptoModuleCallValidator()))
    );

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Kind.CALL_EXPR, ctx -> {
      CallExpression callExpression = (CallExpression) ctx.syntaxNode();
      var qualifiedName = qualifiedNameOrEmpty(callExpression);
      var configs = CALL_EXPRESSION_VALIDATORS.getOrDefault(qualifiedName, List.of());

      configs.forEach(config -> config.validate(ctx, callExpression));
    });
  }


  private static class OpenSslCryptoModuleCallValidator implements CallValidator {
    private static final Set<String> KEY_TYPE_FQNS_TO_CHECK = Set.of("OpenSSL.crypto.TYPE_RSA", "OpenSSL.crypto.TYPE_DSA");

    @Override
    public void validate(SubscriptionContext ctx, CallExpression callExpression) {
      var arguments = callExpression.arguments();
      if (keyTypeNeedsToBeChecked(arguments)) {
        TreeUtils.nthArgumentOrKeywordOptional(1, "bits", arguments)
          .filter(StrongCryptographicKeysCheck::isLessThan2048)
          .ifPresent(arg -> ctx.addIssue(arg, MESSAGE_AT_LEAST_2048_BIT));
      }
    }

    private static boolean keyTypeNeedsToBeChecked(List<Argument> arguments) {
      return TreeUtils.nthArgumentOrKeywordOptional(0, "type", arguments)
        .map(RegularArgument::expression)
        .filter(HasSymbol.class::isInstance)
        .map(HasSymbol.class::cast)
        .map(HasSymbol::symbol)
        .map(Symbol::fullyQualifiedName)
        .map(KEY_TYPE_FQNS_TO_CHECK::contains)
        .orElse(false);
    }
  }

  private static boolean isForbiddenCurve(Expression expression, Set<String> forbiddenStrings) {
    if (expression.getKind() == Kind.STRING_LITERAL) {
      String curveName = ((StringLiteral) expression).trimmedQuotesValue();
      return forbiddenStrings.contains(curveName);
    }
    if (expression.getKind() == Kind.NAME) {
      return Expressions.singleAssignedNonNameValue(((Name) expression))
        .map(v -> isForbiddenCurve(v, forbiddenStrings))
        .orElse(false);
    }
    return false;
  }

  private static boolean isNonCompliantCurve(Expression expression) {
    if (expression instanceof Name name) {
      expression = Expressions.singleAssignedValue(name);
      if (expression == null) {
        return false;
      }
    }
    if (expression instanceof CallExpression callExpression) {
      expression = callExpression.callee();
    }
    if (!expression.is(Kind.QUALIFIED_EXPR)) {
      return false;
    }
    QualifiedExpression qualifiedExpressionTree = (QualifiedExpression) expression;
    if (qualifiedExpressionTree.qualifier() instanceof HasSymbol hasSymbol) {
      Symbol symbol = hasSymbol.symbol();
      if (symbol == null || !"cryptography.hazmat.primitives.asymmetric.ec".equals(symbol.fullyQualifiedName())) {
        return false;
      }
      return CRYPTOGRAPHY_FORBIDDEN_CURVE.matcher(qualifiedExpressionTree.name().name()).matches();
    }
    return false;
  }

  private static boolean isLessThan2048(RegularArgument argument) {
    return CommonValidationUtils.isLessThan(argument.expression(), 2048);
  }

  private static boolean isLessThan65537(RegularArgument argument) {
    return CommonValidationUtils.isLessThan(argument.expression(), 65537);
  }

}

package org.sonar.python.checks.cdk;

import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;
import javax.annotation.Nullable;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.python.tree.TreeUtils;

import static org.sonar.python.checks.cdk.CdkPredicate.isFqnOf;
import static org.sonar.python.checks.cdk.CdkPredicate.isWildcard;
import static org.sonar.python.checks.cdk.CdkUtils.getCall;

@Rule(key = "S6270")
public class IamPolicyPublicAccessCheck extends AbstractIamPolicyStatementCheck {

  private static final String ISSUE_MESSAGE = "Make sure granting public access is safe here.";
  private static final String SECONDARY_MESSAGE = "Related effect.";

  @Override
  protected void checkAllowingPolicyStatement(PolicyStatement policyStatement) {
    CdkUtils.ExpressionFlow principals = policyStatement.principals();

    if (principals == null) {
      return;
    }

    CdkUtils.getListExpression(principals)
      .map(list -> CdkUtils.getListElements(principals.ctx(), list))
      .orElse(Collections.emptyList())
      .forEach(principalElement -> raiseIssueIf(principalElement, isSensitivePrincipal(), policyStatement.effect()));
  }

  @Override
  protected void checkPolicyStatementFromJson(PolicyStatement policyStatement) {
    CdkUtils.ExpressionFlow effect = policyStatement.effect();
    CdkUtils.ExpressionFlow principals = policyStatement.principals();

    if (principals == null || !hasAllowEffect(effect)) {
      return;
    }

    raiseIssueIf(principals, isWildcard(), effect);

    CdkUtils.getDictionary(principals)
      .flatMap(innerDict -> CdkUtils.getDictionaryPair(principals.ctx(), innerDict, "AWS"))
      .map(aws -> getSensitiveExpression(aws.value, isWildcard()))
      .ifPresent(sensitiveAwsPrincipal -> raiseIssueIf(sensitiveAwsPrincipal, isWildcard(), effect));
  }

  private static Predicate<Expression> isSensitivePrincipal() {
    return isFqnOf(List.of("aws_cdk.aws_iam.StarPrincipal", "aws_cdk.aws_iam.AnyPrincipal"))
      .or(isSensitiveArnPrincipal());
  }

  private static Predicate<Expression> isSensitiveArnPrincipal() {
    return expression -> getCall(expression, "aws_cdk.aws_iam.ArnPrincipal")
      .map(callExpression -> TreeUtils.nthArgumentOrKeyword(0, "arn", callExpression.arguments()))
      .map(RegularArgument::expression)
      .filter(isWildcard())
      .isPresent();
  }

  private static void raiseIssueIf(CdkUtils.ExpressionFlow expressionFlow, Predicate<Expression> predicate, @Nullable CdkUtils.ExpressionFlow effect) {
    if (effect != null) {
      expressionFlow.addIssueIf(predicate, ISSUE_MESSAGE, effect.asSecondaryLocation(SECONDARY_MESSAGE));
    } else {
      expressionFlow.addIssueIf(predicate, ISSUE_MESSAGE);
    }
  }
}

package org.sonar.python.checks.cdk;

import java.util.Optional;
import javax.annotation.Nullable;
import org.sonar.check.Rule;

import static org.sonar.python.checks.cdk.CdkPredicate.isWildcard;

@Rule(key = "S6302")
public class PrivilegePolicyCheck extends AbstractIamPolicyStatementCheck {

  private static final String MESSAGE = "Make sure granting all privileges is safe here.";
  private static final String SECONDARY_MESSAGE = "Related effect";

  @Override
  protected void checkAllowingPolicyStatement(PolicyStatement policyStatement) {
    CdkUtils.ExpressionFlow action = policyStatement.actions();

    if (action == null) {
      return;
    }

    Optional.ofNullable(getSensitiveExpression(action, isWildcard()))
      .ifPresent(wildcard -> reportWildcardActionAndEffect(wildcard, policyStatement.effect()));
  }

  private static void reportWildcardActionAndEffect(CdkUtils.ExpressionFlow wildcard, @Nullable CdkUtils.ExpressionFlow effect) {
    PreciseIssue issue = wildcard.ctx().addIssue(wildcard.getLast(), MESSAGE);
    if (effect != null) {
      issue.secondary(effect.asSecondaryLocation(SECONDARY_MESSAGE));
    }
  }
}

package org.sonar.python.checks;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import javax.annotation.Nullable;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.Tree;
import org.sonar.plugins.python.api.symbols.Symbol;

@Rule(key = "S5445")
public class TempFileCreationCheck extends PythonSubscriptionCheck {

  private static final List<String> SUSPICIOUS_CALLS = Arrays.asList("os.tempnam", "os.tmpnam", "tempfile.mktemp");

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Tree.Kind.CALL_EXPR, ctx -> {
      CallExpression callExpr = (CallExpression) ctx.syntaxNode();
      Symbol symbol = callExpr.calleeSymbol();
      isInsecureTempFile(symbol).ifPresent(s -> ctx.addIssue(callExpr, String.format("'%s' is insecure. Use 'tempfile.TemporaryFile' instead", s)));
    });
  }

  private static Optional<String> isInsecureTempFile(@Nullable Symbol symbol) {
    if (symbol == null) {
      return Optional.empty();
    }
    return SUSPICIOUS_CALLS.stream().filter(call -> call.equals(symbol.fullyQualifiedName())).findFirst();
  }
}

package org.sonar.python.checks.hotspots;

import java.util.Arrays;
import java.util.List;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.tree.ArgList;
import org.sonar.plugins.python.api.tree.AssignmentStatement;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.ClassDef;
import org.sonar.plugins.python.api.tree.HasSymbol;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.Tree;
import org.sonar.plugins.python.api.symbols.Symbol;

@Rule(key = "S4792")
public class LoggersConfigurationCheck extends PythonSubscriptionCheck {

  private static final List<String> FUNCTIONS_TO_CHECK = Arrays.asList(
    "logging.basicConfig",
    "logging.disable",
    "logging.setLoggerClass",
    "logging.config.fileConfig",
    "logging.config.dictConfig");

  private static final List<String> LOGGERS_CLASSES = Arrays.asList(
    "logging.Logger",
    "logging.Handler",
    "logging.Filter");

  private static final String MESSAGE = "Make sure that this logger's configuration is safe.";

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Tree.Kind.CALL_EXPR, ctx -> {
      CallExpression callExpressionTree = (CallExpression) ctx.syntaxNode();
      Symbol symbol = callExpressionTree.calleeSymbol();
      if (symbol != null && FUNCTIONS_TO_CHECK.contains(symbol.fullyQualifiedName())) {
        ctx.addIssue(callExpressionTree, MESSAGE);
      }
    });

    context.registerSyntaxNodeConsumer(Tree.Kind.ASSIGNMENT_STMT, ctx -> isSettingLastResort(ctx, (AssignmentStatement) ctx.syntaxNode()));

    context.registerSyntaxNodeConsumer(Tree.Kind.CLASSDEF, ctx -> isClassExtendingLogger(ctx, (ClassDef) ctx.syntaxNode()));
  }

  private static void isClassExtendingLogger(SubscriptionContext ctx, ClassDef classDef) {
    ArgList argList = classDef.args();
    if (argList != null) {
      argList.arguments().stream()
        .filter(argument -> argument.is(Tree.Kind.REGULAR_ARGUMENT))
        .map(RegularArgument.class::cast)
        .map(RegularArgument::expression)
        .filter(expr -> expr instanceof HasSymbol hasSymbol && hasSymbol.symbol() != null)
        .filter(expr -> LOGGERS_CLASSES.contains(((HasSymbol) expr).symbol().fullyQualifiedName()))
        .forEach(expr -> ctx.addIssue(expr, MESSAGE));
    }
  }


  private static void isSettingLastResort(SubscriptionContext ctx, AssignmentStatement assignment) {
    assignment.lhsExpressions().stream()
      .flatMap(exprList -> exprList.expressions().stream())
      .forEach(expr -> {
        if (expr instanceof HasSymbol hasSymbol) {
          Symbol symbol = hasSymbol.symbol();
          if (symbol != null && "logging.lastResort".equals(symbol.fullyQualifiedName())) {
            ctx.addIssue(expr, MESSAGE);
          }
        }
      });
  }
}

package org.sonar.python.checks.hotspots;

import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.symbols.Symbol;
import org.sonar.plugins.python.api.tree.ArgList;
import org.sonar.plugins.python.api.tree.ClassDef;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.HasSymbol;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.Tree;

@Rule(key = "S2257")
public class NonStandardCryptographicAlgorithmCheck extends PythonSubscriptionCheck {
  private static final String MESSAGE = "Make sure using a non-standard cryptographic algorithm is safe here.";

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Tree.Kind.CLASSDEF, NonStandardCryptographicAlgorithmCheck::checkCreatingCustomHasher);
  }

  private static String getQualifiedName(Expression node) {
    if (node instanceof HasSymbol hasSymbol) {
      Symbol symbol = hasSymbol.symbol();
      return symbol != null ? symbol.fullyQualifiedName() : "";
    }
    return "";
  }

  private static void checkCreatingCustomHasher(SubscriptionContext ctx) {
    ClassDef classDef = (ClassDef) ctx.syntaxNode();
    String qualifiedName = getQualifiedName(classDef.name());
    if (qualifiedName != null && qualifiedName.startsWith("django.contrib.auth.hashers")) {
      return;
    }
    ArgList argList = classDef.args();
    if (argList != null) {
      argList.arguments()
        .stream()
        .filter(arg -> arg.is(Tree.Kind.REGULAR_ARGUMENT))
        .map(RegularArgument.class::cast)
        .filter(arg -> "django.contrib.auth.hashers.BasePasswordHasher".equals(getQualifiedName(arg.expression())))
        .forEach(arg -> ctx.addIssue(arg, MESSAGE));
    }
  }
}

package org.sonar.python.checks.hotspots;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.symbols.FunctionSymbol;
import org.sonar.plugins.python.api.symbols.Symbol;
import org.sonar.plugins.python.api.tree.Argument;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.Decorator;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.FileInput;
import org.sonar.plugins.python.api.tree.FunctionDef;
import org.sonar.plugins.python.api.tree.ListLiteral;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.StringLiteral;
import org.sonar.python.semantic.FunctionSymbolImpl;
import org.sonar.python.tree.FunctionDefImpl;
import org.sonar.python.tree.TreeUtils;

import static org.sonar.plugins.python.api.tree.Tree.Kind.CALL_EXPR;
import static org.sonar.plugins.python.api.tree.Tree.Kind.FILE_INPUT;
import static org.sonar.plugins.python.api.tree.Tree.Kind.FUNCDEF;
import static org.sonar.plugins.python.api.tree.Tree.Kind.LIST_LITERAL;
import static org.sonar.plugins.python.api.tree.Tree.Kind.REGULAR_ARGUMENT;
import static org.sonar.plugins.python.api.tree.Tree.Kind.STRING_LITERAL;
import static org.sonar.python.tree.TreeUtils.argumentByKeyword;
import static org.sonar.python.tree.TreeUtils.getSymbolFromTree;

@Rule(key = "S3752")
public class UnsafeHttpMethodsCheck extends PythonSubscriptionCheck {

  private static final Set<String> SAFE_HTTP_METHODS = new HashSet<>(Arrays.asList("GET", "HEAD", "OPTIONS"));
  private static final Set<String> UNSAFE_HTTP_METHODS = new HashSet<>(Arrays.asList("POST", "PUT", "DELETE"));
  private static final Set<String> COMPLIANT_DECORATORS = new HashSet<>(Arrays.asList(
    "django.views.decorators.http.require_POST",
    "django.views.decorators.http.require_GET",
    "django.views.decorators.http.require_safe"
  ));
  private static final String MESSAGE = "Make sure allowing safe and unsafe HTTP methods is safe here.";

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(FUNCDEF, ctx -> {
      FunctionDef functionDef = (FunctionDef) ctx.syntaxNode();
      if (isDjangoView(functionDef)) {
        checkDjangoView(functionDef, ctx);
      } else {
        getFlaskViewDecorator(functionDef).ifPresent(callExpression -> checkFlaskView(callExpression, ctx));
      }
    });
  }

  private static void checkDjangoView(FunctionDef functionDef, SubscriptionContext ctx) {
    for (Decorator decorator : functionDef.decorators()) {
      if (getSymbolFromTree(decorator.expression())
        .filter(symbol -> symbol.fullyQualifiedName() == null || COMPLIANT_DECORATORS.contains(symbol.fullyQualifiedName()))
        .isPresent()) {
        return;
      }
      if (decorator.expression().is(CALL_EXPR)) {
        CallExpression callExpression = (CallExpression) decorator.expression();
        Symbol symbol = callExpression.calleeSymbol();
        if (symbol != null && "django.views.decorators.http.require_http_methods".equals(symbol.fullyQualifiedName())) {
          checkRequireHttpMethodsDecorator(ctx, callExpression);
          return;
        }
      }
    }
    ctx.addIssue(functionDef.name(), MESSAGE);
  }

  private static void checkRequireHttpMethodsDecorator(SubscriptionContext ctx, CallExpression callExpression) {
    List<Argument> arguments = callExpression.arguments();
    if (!arguments.isEmpty() && hasBothUnsafeAndSafeHttpMethods(arguments.get(0))) {
      ctx.addIssue(callExpression, MESSAGE);
    }
  }

  private static boolean hasBothUnsafeAndSafeHttpMethods(Argument argument) {
    boolean hasSafeHttpMethod = false;
    boolean hasUnsafeHttpMethod = false;
    if (argument.is(REGULAR_ARGUMENT) && ((RegularArgument) argument).expression().is(LIST_LITERAL)) {
      ListLiteral listLiteral = (ListLiteral) ((RegularArgument) argument).expression();
      for (Expression expression : listLiteral.elements().expressions()) {
        if (expression.is(STRING_LITERAL)) {
          String value = ((StringLiteral) expression).trimmedQuotesValue();
          if (SAFE_HTTP_METHODS.contains(value)) {
            hasSafeHttpMethod = true;
          } else if (UNSAFE_HTTP_METHODS.contains(value)) {
            hasUnsafeHttpMethod = true;
          }
        }
      }
    }
    return hasSafeHttpMethod && hasUnsafeHttpMethod;
  }

  private static boolean isDjangoView(FunctionDef functionDef) {
    FunctionSymbol functionSymbol = ((FunctionDefImpl) functionDef).functionSymbol();
    return Optional.ofNullable(functionSymbol)
      .map(FunctionSymbolImpl.class::cast)
      .filter(FunctionSymbolImpl::isDjangoView)
      .isPresent();
  }

  private static Optional<CallExpression> getFlaskViewDecorator(FunctionDef functionDef) {
    return functionDef.decorators().stream()
      .map(Decorator::expression)
      .filter(expression -> expression.is(CALL_EXPR))
      .map(CallExpression.class::cast)
      .filter(UnsafeHttpMethodsCheck::isFlaskRouteDecorator)
      .findFirst();
  }

  private static boolean isFlaskRouteDecorator(CallExpression callExpression) {
    Symbol calleeSymbol = callExpression.calleeSymbol();
    if (calleeSymbol == null) {
      return false;
    }
    return "route".equals(calleeSymbol.name());
  }

  private static void checkFlaskView(CallExpression callExpression, SubscriptionContext ctx) {
    RegularArgument methodsArg = argumentByKeyword("methods", callExpression.arguments());
    if (methodsArg != null && hasBothUnsafeAndSafeHttpMethods(methodsArg) && isFlaskImported(callExpression)) {
      ctx.addIssue(callExpression, MESSAGE);
    }
  }

  private static boolean isFlaskImported(CallExpression callExpression) {
    return Optional.ofNullable(TreeUtils.firstAncestorOfKind(callExpression, FILE_INPUT))
      .filter(fileInput -> ((FileInput) fileInput).globalVariables().stream()
          .map(Symbol::fullyQualifiedName)
          .filter(Objects::nonNull)
          .anyMatch(fqn -> fqn.contains("flask")))
      .isPresent();
  }
}

package org.sonar.python.checks.hotspots;

import java.util.ArrayList;
import java.util.Collection;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import org.sonar.check.Rule;
import org.sonar.check.RuleProperty;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.tree.AnnotatedAssignment;
import org.sonar.plugins.python.api.tree.AssignmentStatement;
import org.sonar.plugins.python.api.tree.DictionaryLiteral;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.KeyValuePair;
import org.sonar.plugins.python.api.tree.Name;
import org.sonar.plugins.python.api.tree.ParameterList;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.StringLiteral;
import org.sonar.plugins.python.api.tree.Tree;
import org.sonar.python.checks.utils.Expressions;
import org.sonarsource.analyzer.commons.ShannonEntropy;

@Rule(key = "S6418")
public class HardCodedCredentialsEntropyCheck extends PythonSubscriptionCheck {

  private static final String DEFAULT_SECRET_KEYWORDS = "api[_.-]?key,auth,credential,secret,token";

  private static final String DEFAULT_RANDOMNESS_SENSIBILITY = "3.0";

  private static final Pattern POSTVALIDATION_PATTERN = Pattern.compile("[a-zA-Z0-9_.+/~$-]([a-zA-Z0-9_.+/=~$-]|\\\\\\\\(?![ntr\"])){14,1022}[a-zA-Z0-9_.+/=~$-]");

  private static final String MESSAGE = "\"%s\" detected here, make sure this is not a hard-coded secret.";

  private Collection<Pattern> patterns = null;

  @RuleProperty(
    key = "credentialWords",
    description = "Comma separated list of words identifying potential credentials",
    defaultValue = DEFAULT_SECRET_KEYWORDS)
  public String secretKeyWords = DEFAULT_SECRET_KEYWORDS;

  @RuleProperty(
    key = "randomnessSensibility",
    description = "Allows to tune the Randomness Sensibility (from 0 to 10)",
    defaultValue = DEFAULT_RANDOMNESS_SENSIBILITY)
  public double randomnessSensibility = Double.parseDouble(DEFAULT_RANDOMNESS_SENSIBILITY);

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Tree.Kind.ASSIGNMENT_STMT, this::checkAssignment);
    context.registerSyntaxNodeConsumer(Tree.Kind.ANNOTATED_ASSIGNMENT, this::checkAnnotatedAssignment);
    context.registerSyntaxNodeConsumer(Tree.Kind.PARAMETER_LIST, this::checkParameterList);
    context.registerSyntaxNodeConsumer(Tree.Kind.REGULAR_ARGUMENT, this::checkRegularArgument);
    context.registerSyntaxNodeConsumer(Tree.Kind.DICTIONARY_LITERAL, this::checkDictionaryLiteral);
  }

  private void patternMatch(Name name, Tree location, String value, SubscriptionContext subscriptionContext) {
    patternMatch(name.name(), location, value, subscriptionContext);
  }

  private void patternMatch(String name, Tree location, String value, SubscriptionContext subscriptionContext) {
    if (!valuePassesPostValidation(value) || !entropyShouldRaise(value)) {
      return;
    }
    patterns().stream()
      .filter(pattern -> pattern.matcher(name).matches())
      .findFirst()
      .ifPresent(pattern -> subscriptionContext.addIssue(location, String.format(MESSAGE, name)));
  }

  private void checkParameterList(SubscriptionContext subscriptionContext) {
    var parameterList = (ParameterList) subscriptionContext.syntaxNode();
    parameterList.nonTuple().stream()
      .filter(parameter -> parameter.name() != null)
      .filter(parameter -> parameter.defaultValue() != null)
      .filter(parameter -> parameter.defaultValue().is(Tree.Kind.STRING_LITERAL))
      .forEach(parameter -> {
        var value = ((StringLiteral) parameter.defaultValue()).trimmedQuotesValue();
        patternMatch(parameter.name(), parameter.defaultValue(), value, subscriptionContext);
      });
  }

  private void checkDictionaryLiteral(SubscriptionContext subscriptionContext) {
    var dictionaryLiteral = (DictionaryLiteral) subscriptionContext.syntaxNode();
    dictionaryLiteral.elements().stream().filter(e -> e.is(Tree.Kind.KEY_VALUE_PAIR))
      .map(KeyValuePair.class::cast)
      .filter(keyValuePair -> keyValuePair.value().is(Tree.Kind.STRING_LITERAL))
      .filter(keyValuePair -> keyValuePair.key().is(Tree.Kind.STRING_LITERAL))
      .forEach(keyValuePair -> {
        var value = ((StringLiteral) keyValuePair.value()).trimmedQuotesValue();
        var key = ((StringLiteral) keyValuePair.key()).trimmedQuotesValue();
        patternMatch(key, keyValuePair.value(), value, subscriptionContext);
      });
  }

  private void checkRegularArgument(SubscriptionContext subscriptionContext) {
    var regularArgument = (RegularArgument) subscriptionContext.syntaxNode();
    var keywordArgument = regularArgument.keywordArgument();

    if (keywordArgument != null && regularArgument.expression() instanceof StringLiteral expression) {
      var value = expression.trimmedQuotesValue();
      patternMatch(keywordArgument, regularArgument, value, subscriptionContext);
    }
  }

  private void checkAnnotatedAssignment(SubscriptionContext subscriptionContext) {
    var annotatedAssignment = (AnnotatedAssignment) subscriptionContext.syntaxNode();
    var assignedValue = annotatedAssignment.assignedValue();
    var assignedVariable = annotatedAssignment.variable();
    if (assignedValue instanceof StringLiteral stringLiteral && assignedVariable instanceof Name name) {
      patternMatch(name, assignedValue, stringLiteral.trimmedQuotesValue(), subscriptionContext);
    }
  }

  private void checkAssignment(SubscriptionContext subscriptionContext) {
    var expressions = new ArrayList<Expression>();
    var assignment = (AssignmentStatement) subscriptionContext.syntaxNode();
    var assignedValue = assignment.assignedValue();

    if (assignedValue.is(Tree.Kind.TUPLE)) {
      expressions.addAll(Expressions.getExpressionsFromRhs(assignedValue));
    } else {
      expressions.add(assignedValue);
    }

    expressions.stream()
      .filter(StringLiteral.class::isInstance)
      .map(StringLiteral.class::cast)
      .forEach(expression -> Expressions.getAssignedName(expression)
        .ifPresent(name -> {
          var value = expression.trimmedQuotesValue();
          patternMatch(name, expression, value, subscriptionContext);
        }));
  }

  private static boolean valuePassesPostValidation(String value) {
    return POSTVALIDATION_PATTERN.matcher(value).matches();
  }

  private boolean entropyShouldRaise(String value) {
    return ShannonEntropy.calculate(value) > randomnessSensibility;
  }

  private Collection<Pattern> patterns() {
    if (patterns == null) {
      patterns = Stream.of(secretKeyWords.split(","))
        .map(word -> Pattern.compile("(" + word + ")", Pattern.CASE_INSENSITIVE))
        .toList();
    }
    return patterns;
  }

}

package org.sonar.python.checks.hotspots;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.function.Predicate;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.TriBool;
import org.sonar.plugins.python.api.symbols.Symbol;
import org.sonar.plugins.python.api.symbols.Usage;
import org.sonar.plugins.python.api.tree.AssignmentStatement;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.HasSymbol;
import org.sonar.plugins.python.api.tree.Name;
import org.sonar.plugins.python.api.tree.QualifiedExpression;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.Tree;
import org.sonar.plugins.python.api.types.v2.PythonType;
import org.sonar.python.checks.utils.Expressions;
import org.sonar.python.semantic.v2.SymbolV2;
import org.sonar.python.semantic.v2.UsageV2;
import org.sonar.python.tree.TreeUtils;
import org.sonar.python.types.v2.TypeCheckBuilder;

@Rule(key = "S5527")
public class UnverifiedHostnameCheck extends PythonSubscriptionCheck {

  private static final String MESSAGE = "Enable server hostname verification on this SSL/TLS connection.";
  private static final String SECONDARY_OPENSSL = "This context does not perform hostname verification.";
  private static final String SECONDARY_DISABLED = "Hostname verification is disabled here.";

  private static final Set<String> SECURE_BY_DEFAULT = new HashSet<>(Arrays.asList("ssl.create_default_context", "ssl._create_default_https_context"));
  private static final Set<String> UNSECURE_BY_DEFAULT = new HashSet<>(Arrays.asList("ssl._create_unverified_context", "ssl._create_stdlib_context"));

  private static final Set<String> UNSAFE_PROTOCOLS = Set.of(
    "ssl.PROTOCOL_SSLv23",
    "ssl.PROTOCOL_TLS",
    "ssl.PROTOCOL_SSLv3",
    "ssl.PROTOCOL_TLSv1",
    "ssl.PROTOCOL_TLSv1_1",
    "ssl.PROTOCOL_TLSv1_2"
  );

  private static Set<String> functionsToCheck;

  private TypeCheckBuilder openSSLConnectionTypeCheckBuilder;
  private TypeCheckBuilder openSSLContextTypeCheckBuilder;
  private TypeCheckBuilder sslContextTypeCheckBuilder;

  private static Set<String> functionsToCheck() {
    if (functionsToCheck == null) {
      functionsToCheck = new HashSet<>();
      functionsToCheck.addAll(SECURE_BY_DEFAULT);
      functionsToCheck.addAll(UNSECURE_BY_DEFAULT);
    }
    return Collections.unmodifiableSet(functionsToCheck);
  }

  private static void checkSuspiciousCall(CallExpression callExpression, Symbol calleeSymbol, SubscriptionContext ctx) {
    Tree parent = TreeUtils.firstAncestorOfKind(callExpression, Tree.Kind.ASSIGNMENT_STMT, Tree.Kind.CALL_EXPR);
    if (parent == null) {
      return;
    }
    if (parent.is(Tree.Kind.ASSIGNMENT_STMT)) {
      Expression lhs = ((AssignmentStatement) parent).lhsExpressions().get(0).expressions().get(0);
      if (lhs instanceof HasSymbol hasSymbol) {
        Symbol symbol = hasSymbol.symbol();
        if (symbol == null) {
          return;
        }
        if (isUnsafeContext(calleeSymbol, symbol)) {
          ctx.addIssue(callExpression, MESSAGE);
        }
      }
    } else if (opensUnsecureConnection(calleeSymbol, (CallExpression) parent)) {
      ctx.addIssue(callExpression, MESSAGE);
    }
  }

  private static boolean isUnsafeContext(Symbol calleeSymbol, Symbol symbol) {
    for (Usage usage : symbol.usages()) {
      if (usage.kind().equals(Usage.Kind.OTHER)) {
        QualifiedExpression qualifiedExpression = (QualifiedExpression) TreeUtils.firstAncestorOfKind(usage.tree(), Tree.Kind.QUALIFIED_EXPR);
        if (qualifiedExpression != null && "check_hostname".equals(qualifiedExpression.name().name())) {
          AssignmentStatement assignmentStatement = (AssignmentStatement) TreeUtils.firstAncestorOfKind(qualifiedExpression, Tree.Kind.ASSIGNMENT_STMT);
          if (assignmentStatement != null) {
            return Expressions.isFalsy(assignmentStatement.assignedValue());
          }
        }
      }
    }
    return UNSECURE_BY_DEFAULT.contains(calleeSymbol.fullyQualifiedName());
  }

  private static boolean opensUnsecureConnection(Symbol calleeSymbol, CallExpression callExpr) {
    Symbol parentCalleeSymbol = callExpr.calleeSymbol();
    return parentCalleeSymbol != null && "urllib.request.urlopen".equals(parentCalleeSymbol.fullyQualifiedName())
      && UNSECURE_BY_DEFAULT.contains(calleeSymbol.fullyQualifiedName());
  }

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Tree.Kind.CALL_EXPR, this::checkCallExpression);
    context.registerSyntaxNodeConsumer(Tree.Kind.FILE_INPUT, ctx -> {
      openSSLConnectionTypeCheckBuilder = ctx.typeChecker().typeCheckBuilder().isTypeWithName("OpenSSL.SSL.Connection");
      openSSLContextTypeCheckBuilder = ctx.typeChecker().typeCheckBuilder().isInstanceOf("OpenSSL.SSL.Context");
      sslContextTypeCheckBuilder = ctx.typeChecker().typeCheckBuilder().isTypeWithName("ssl.SSLContext");
    });
  }

  private void checkCallExpression(SubscriptionContext ctx) {
    CallExpression callExpression = (CallExpression) ctx.syntaxNode();
    Symbol calleeSymbol = callExpression.calleeSymbol();
    if (calleeSymbol != null && functionsToCheck().contains(calleeSymbol.fullyQualifiedName())) {
      checkSuspiciousCall(callExpression, calleeSymbol, ctx);
    }
    checkOpenSSLConnection(ctx, callExpression);
    checkSSLContext(ctx, callExpression);
  }

  private void checkSSLContext(SubscriptionContext ctx, CallExpression callExpression) {
    Expression callee = callExpression.callee();
    PythonType pythonType = callee.typeV2();

    if (sslContextTypeCheckBuilder.check(pythonType) != TriBool.TRUE) {
      return;
    }

    Optional<Symbol> protocolSymbolOpt = getProtocolSymbol(callExpression);
    if (protocolSymbolOpt.isEmpty()) {
      return;
    }

    Symbol protocolSymbol = protocolSymbolOpt.get();
    String protocolFQN = protocolSymbol.fullyQualifiedName();
    if (protocolFQN == null) {
      return;
    }

    Tree parent = TreeUtils.firstAncestorOfKind(callExpression, Tree.Kind.ASSIGNMENT_STMT);
    if (parent == null) {

      if (UNSAFE_PROTOCOLS.contains(protocolFQN)) {
        ctx.addIssue(callExpression, MESSAGE);
      }
      return;
    }

    Optional<SymbolV2> contextSymbol = getContextSymbol((AssignmentStatement) parent);
    if (contextSymbol.isEmpty()) {
      return;
    }

    if (UNSAFE_PROTOCOLS.contains(protocolFQN)) {

      Optional<AssignmentStatement> hostnameEnabledAssignment = findCheckHostnameStatement(contextSymbol.get(), Expressions::isTruthy);
      if (hostnameEnabledAssignment.isEmpty()) {
        ctx.addIssue(callExpression, MESSAGE);
      }
    } else {

      Optional<AssignmentStatement> hostnameDisabledAssignment = findCheckHostnameStatement(contextSymbol.get(), Expressions::isFalsy);
      hostnameDisabledAssignment.ifPresent(assignment -> {
        PreciseIssue issue = ctx.addIssue(callee, MESSAGE);
        issue.secondary(assignment, SECONDARY_DISABLED);
      });
    }
  }

  private static Optional<Symbol> getProtocolSymbol(CallExpression callExpression) {
    return Optional.ofNullable(TreeUtils.nthArgumentOrKeyword(0, "protocol", callExpression.arguments()))
      .map(RegularArgument::expression)
      .filter(HasSymbol.class::isInstance)
      .map(expr -> ((HasSymbol) expr).symbol());
  }

  private static Optional<SymbolV2> getContextSymbol(AssignmentStatement assignmentStatement) {
    return Optional.ofNullable(assignmentStatement.lhsExpressions().get(0).expressions().get(0))
      .filter(Name.class::isInstance)
      .map(expr -> ((Name) expr).symbolV2());
  }

  private static Optional<AssignmentStatement> findCheckHostnameStatement(SymbolV2 contextSymbol, Predicate<Expression> valueCheck) {
    return contextSymbol.usages().stream()
      .map(UsageV2::tree)
      .map(Tree::parent)
      .filter(QualifiedExpression.class::isInstance)
      .map(QualifiedExpression.class::cast)
      .filter(qe -> "check_hostname".equals(qe.name().name()))
      .map(t -> TreeUtils.firstAncestorOfKind(t, Tree.Kind.ASSIGNMENT_STMT))
      .filter(Objects::nonNull)
      .map(AssignmentStatement.class::cast)
      .filter(a -> valueCheck.test(a.assignedValue()))
      .findFirst();
  }

  private void checkOpenSSLConnection(SubscriptionContext ctx, CallExpression callExpression) {
    Expression callee = callExpression.callee();
    PythonType pythonType = callee.typeV2();

    if (openSSLConnectionTypeCheckBuilder.check(pythonType) != TriBool.TRUE) {
      return;
    }

    RegularArgument contextArg = TreeUtils.nthArgumentOrKeyword(0, "context", callExpression.arguments());
    if (contextArg == null) {
      return;
    }

    Expression contextExpr = contextArg.expression();
    PythonType contextType = contextExpr.typeV2();
    if (openSSLContextTypeCheckBuilder.check(contextType) == TriBool.TRUE) {
      PreciseIssue issue = ctx.addIssue(callee, MESSAGE);
      Expressions.ifNameGetSingleAssignedNonNameValue(contextExpr)
        .ifPresentOrElse(e -> issue.secondary(e, SECONDARY_OPENSSL),
          () -> issue.secondary(contextExpr, SECONDARY_OPENSSL)
        );
    }
  }
}

package org.sonar.python.checks.hotspots;

import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Stream;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.tree.Argument;
import org.sonar.plugins.python.api.tree.RegularArgument;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.DictionaryLiteral;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.KeyValuePair;
import org.sonar.plugins.python.api.tree.Name;
import org.sonar.plugins.python.api.tree.UnpackingExpression;
import org.sonar.plugins.python.api.tree.StringLiteral;
import org.sonar.plugins.python.api.tree.Tree.Kind;
import org.sonar.python.checks.utils.Expressions;
import org.sonar.plugins.python.api.symbols.Symbol;

@Rule(key = "S5247")
public class DisabledHtmlAutoEscapeCheck extends PythonSubscriptionCheck {

  private static final String AUTO_ESCAPE = "autoescape";
  private static final String MESSAGE = "Make sure disabling auto-escaping feature is safe here.";
  private static final Set<String> JINJA_ENVIRONMNENT_FQN_SET;
  static {
    Set<String> environmentFqnSet = new HashSet<>();
    environmentFqnSet.add("jinja2.Environment");
    environmentFqnSet.add("jinja2.environment.Environment");
    JINJA_ENVIRONMNENT_FQN_SET = environmentFqnSet;
  }

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Kind.CALL_EXPR, ctx ->
      checkCallExpression(ctx, (CallExpression) ctx.syntaxNode())
    );
    context.registerSyntaxNodeConsumer(Kind.KEY_VALUE_PAIR, ctx ->
      checkKeyValuePair(ctx, (KeyValuePair) ctx.syntaxNode())
    );
  }

  private void checkKeyValuePair(SubscriptionContext ctx, KeyValuePair keyValue) {
    if (!"settings.py".equals(ctx.pythonFile().fileName())) {
      return;
    }
    if (isStringLiteral(keyValue.key(), AUTO_ESCAPE) && Expressions.isFalsy(keyValue.value())) {
      ctx.addIssue(keyValue, message());
    }
  }

  private static boolean isStringLiteral(Expression tree, String testedValue) {
    return tree.is(Kind.STRING_LITERAL) && testedValue.equals(Expressions.unescape((StringLiteral) tree));
  }

  private void checkCallExpression(SubscriptionContext ctx, CallExpression call) {
    Symbol symbol = call.calleeSymbol();

    if (symbol != null && JINJA_ENVIRONMNENT_FQN_SET.contains(symbol.fullyQualifiedName())) {
      List<Argument> arguments = call.arguments();

      for (Argument argument : arguments) {
        if (argument.is(Kind.UNPACKING_EXPR)) {
          Expression expression = ((UnpackingExpression) argument).expression();
          if (expression.is(Kind.NAME)) {
            checkJinjaOptions(ctx, call, (Name) expression);
            return;
          }
        }
      }

      Stream<RegularArgument> autoEscapeArgs = arguments.stream()
        .filter(arg -> arg.is(Kind.REGULAR_ARGUMENT))
        .map(RegularArgument.class::cast)
        .filter(DisabledHtmlAutoEscapeCheck::isAutoEscapeArgument);
      if (autoEscapeArgs.allMatch(arg -> Expressions.isFalsy(arg.expression()))) {
        ctx.addIssue(call, message());
      }
    }
  }

  private void checkJinjaOptions(SubscriptionContext ctx, CallExpression call, Name expression) {
    Expression options = Expressions.singleAssignedValue(expression);
    if (options != null && options.is(Kind.DICTIONARY_LITERAL)) {
      DictionaryLiteral dict = (DictionaryLiteral) options;
      Optional<Expression> autoEscapeOption = dict.elements().stream()
        .filter(elem -> elem.is(Kind.KEY_VALUE_PAIR))
        .map(KeyValuePair.class::cast)
        .filter(kv -> isStringLiteral(kv.key(), AUTO_ESCAPE))
        .map(KeyValuePair::value)
        .findFirst();
      if (!autoEscapeOption.isPresent() || Expressions.isFalsy(autoEscapeOption.get())) {
        ctx.addIssue(call, message());
      }
    }
  }

  private static boolean isAutoEscapeArgument(RegularArgument argument) {
    Name keyword = argument.keywordArgument();
    return keyword != null && AUTO_ESCAPE.equals(keyword.name());
  }

  String message() {
    return MESSAGE;
  }
}

package org.sonar.python.checks.cdk;

import java.util.function.BiConsumer;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.tree.CallExpression;

import static org.sonar.python.checks.cdk.CdkPredicate.isNone;
import static org.sonar.python.checks.cdk.CdkUtils.getArgument;

@Rule(key = "S6327")
public class DisabledSNSTopicEncryptionCheck extends AbstractCdkResourceCheck {
  private static final String OMITTING_MESSAGE = "Omitting \"%s\" disables SNS topics encryption. Make sure it is safe here.";

  @Override
  protected void registerFqnConsumer() {
    checkFqn("aws_cdk.aws_sns.Topic", checkTopic("master_key"));
    checkFqn("aws_cdk.aws_sns.CfnTopic", checkTopic("kms_master_key_id"));
  }

  private static BiConsumer<SubscriptionContext, CallExpression> checkTopic(String argMasterKeyName) {
    return (ctx, callExpression) -> getArgument(ctx, callExpression, argMasterKeyName)
      .ifPresentOrElse(
        argMasterKey -> argMasterKey.addIssueIf(isNone(), omittingMessage(argMasterKeyName)),
        () -> ctx.addIssue(callExpression.callee(), omittingMessage(argMasterKeyName)));
  }

  private static String omittingMessage(String argName) {
    return String.format(OMITTING_MESSAGE, argName);
  }
}

package org.sonar.python.checks;

import java.util.List;
import java.util.Map;
import javax.annotation.CheckForNull;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.PythonSubscriptionCheck;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.tree.ClassDef;
import org.sonar.plugins.python.api.tree.Expression;
import org.sonar.plugins.python.api.tree.ExpressionStatement;
import org.sonar.plugins.python.api.tree.FunctionDef;
import org.sonar.plugins.python.api.tree.QualifiedExpression;
import org.sonar.plugins.python.api.tree.ReturnStatement;
import org.sonar.plugins.python.api.tree.Statement;
import org.sonar.plugins.python.api.tree.Token;
import org.sonar.plugins.python.api.tree.Tree;
import org.sonar.plugins.python.api.types.BuiltinTypes;
import org.sonar.plugins.python.api.types.InferredType;
import org.sonar.python.checks.utils.CheckUtils;
import org.sonar.python.tree.TreeUtils;
import org.sonar.python.tree.TupleImpl;
import org.sonar.python.types.v2.TypeCheckBuilder;

@Rule(key = "S935")
public class SpecialMethodReturnTypeCheck extends PythonSubscriptionCheck {

  private static final Map<String, String> METHOD_TO_RETURN_TYPE = Map.of(
    "__bool__", BuiltinTypes.BOOL,
    "__index__", BuiltinTypes.INT,
    "__repr__", BuiltinTypes.STR,
    "__str__", BuiltinTypes.STR,
    "__bytes__", BuiltinTypes.BYTES,
    "__hash__", BuiltinTypes.INT,
    "__format__", BuiltinTypes.STR,
    "__getnewargs__", BuiltinTypes.TUPLE,
    "__getnewargs_ex__", BuiltinTypes.TUPLE,
    "__len__", BuiltinTypes.INT);

  private static final String INVALID_RETURN_TYPE_MESSAGE = "Return a value of type `%s` here.";
  private static final String INVALID_RETURN_TYPE_MESSAGE_NO_LOCATION = "Return a value of type `%s` in this method.";
  private static final String NO_RETURN_STMTS_MESSAGE = INVALID_RETURN_TYPE_MESSAGE_NO_LOCATION
    + " Consider explicitly raising a TypeError if this class is not meant to support this method.";
  private static final String COROUTINE_METHOD_MESSAGE = INVALID_RETURN_TYPE_MESSAGE_NO_LOCATION + " The method can not be a coroutine and have the `async` keyword.";
  private static final String GENERATOR_METHOD_MESSAGE = INVALID_RETURN_TYPE_MESSAGE_NO_LOCATION + " The method can not be a generator and contain `yield` expressions.";
  private static final String INVALID_GETNEWARGSEX_TUPLE_MESSAGE = String.format(INVALID_RETURN_TYPE_MESSAGE, "tuple[tuple, dict]");
  private static final String INVALID_GETNEWARGSEX_ELEMENT_COUNT_MESSAGE = INVALID_GETNEWARGSEX_TUPLE_MESSAGE
    + " A tuple of two elements was expected but found tuple with %d element(s).";

  private TypeCheckBuilder isTorchDataSetTypeCheck;

  @Override
  public void initialize(Context context) {
    context.registerSyntaxNodeConsumer(Tree.Kind.FILE_INPUT, this::setupTypeChecks);
    context.registerSyntaxNodeConsumer(Tree.Kind.CLASSDEF, ctx -> checkClassDefinition(ctx, (ClassDef) ctx.syntaxNode()));
  }

  private void setupTypeChecks(SubscriptionContext ctx) {
    isTorchDataSetTypeCheck = ctx.typeChecker().typeCheckBuilder().isSubtypeOf("torch.utils.data.Dataset");
  }

  private void checkClassDefinition(SubscriptionContext ctx, ClassDef classDef) {
    for (var methodDef : TreeUtils.topLevelFunctionDefs(classDef)) {
      checkFunctionDefinition(ctx, methodDef, CheckUtils.mustBeAProtocolLike(classDef));
    }
  }

  private void checkFunctionDefinition(SubscriptionContext ctx, FunctionDef funDef, boolean classIsProtocolLike) {
    String funNameString = funDef.name().name();
    String expectedReturnType = METHOD_TO_RETURN_TYPE.get(funNameString);
    if (expectedReturnType == null) {
      return;
    }

    ReturnCheckUtils.addIssueIfAsync(ctx, funDef, String.format(COROUTINE_METHOD_MESSAGE, expectedReturnType));

    ReturnCheckUtils.ReturnStmtCollector returnStmtCollector = ReturnCheckUtils.ReturnStmtCollector.collect(funDef);
    List<Token> yieldKeywords = returnStmtCollector.getYieldKeywords();
    for (Token yieldKeyword : yieldKeywords) {
      ctx.addIssue(yieldKeyword, String.format(GENERATOR_METHOD_MESSAGE, expectedReturnType));
    }

    if (hasOnlyEllipsisOrDocStrBody(funDef)) {
      return;
    }

    List<ReturnStatement> returnStmts = returnStmtCollector.getReturnStmts();





    if (returnStmts.isEmpty() &&
      yieldKeywords.isEmpty() &&
      !returnStmtCollector.raisesExceptions() &&
      !CheckUtils.isAbstract(funDef) &&
      !classIsProtocolLike) {
      ctx.addIssue(funDef.defKeyword(), funDef.colon(), String.format(NO_RETURN_STMTS_MESSAGE, expectedReturnType));
      return;
    }

    for (ReturnStatement returnStmt : returnStmts) {
      checkReturnStmt(ctx, funNameString, expectedReturnType, returnStmt);
    }
  }

  private static boolean hasOnlyEllipsisOrDocStrBody(FunctionDef funDef) {
    var statements = funDef.body().statements();
    if (statements.size() != 1) {
      return false;
    }

    Statement statement = statements.get(0);
    if (statement instanceof ExpressionStatement expressionStmnt) {
      var expressions = expressionStmnt.expressions();
      if (expressions.size() == 1) {
        return expressions.get(0).is(Tree.Kind.ELLIPSIS, Tree.Kind.STRING_LITERAL);
      }
    }
    return false;
  }


  private void checkReturnStmt(SubscriptionContext ctx, String methodName, String expectedReturnType, ReturnStatement returnStmt) {
    List<Expression> returnedExpressions = returnStmt.expressions();
    if (returnedExpressions.isEmpty()) {
      ctx.addIssue(returnStmt.returnKeyword(), String.format(INVALID_RETURN_TYPE_MESSAGE_NO_LOCATION, expectedReturnType));
      return;
    }

    if ("__len__".equals(methodName) && isDatasetLenNoncompliant(returnStmt)) {
      ReturnCheckUtils.addIssueOnReturnedExpressions(ctx, returnStmt, String.format(INVALID_RETURN_TYPE_MESSAGE, expectedReturnType));
      return;
    }

    InferredType returnStmtType = returnStmt.returnValueType();

    if (!returnStmtType.canBeOrExtend(expectedReturnType)) {
      ReturnCheckUtils.addIssueOnReturnedExpressions(ctx, returnStmt, String.format(INVALID_RETURN_TYPE_MESSAGE, expectedReturnType));
      return;
    }

    if ("__getnewargs_ex__".equals(methodName)) {
      isGetNewArgsExCompliant(ctx, returnStmt);
    }
  }

  private static void isGetNewArgsExCompliant(SubscriptionContext ctx, ReturnStatement returnStatement) {
    List<Expression> returnedExpressions = returnStatement.expressions();
    int numReturnedExpressions = returnedExpressions.size();













    if (numReturnedExpressions == 1) {
      Expression firstExpression = returnedExpressions.get(0);
      if (firstExpression instanceof TupleImpl tupleImpl) {

        returnedExpressions = tupleImpl.elements();
        numReturnedExpressions = returnedExpressions.size();
      } else {




        return;
      }
    }

    if (numReturnedExpressions != 2) {
      ReturnCheckUtils.addIssueOnReturnedExpressions(ctx, returnStatement, String.format(INVALID_GETNEWARGSEX_ELEMENT_COUNT_MESSAGE, numReturnedExpressions));
      return;
    }


    Expression firstElement = returnedExpressions.get(0);
    Expression secondElement = returnedExpressions.get(1);

    if (!firstElement.type().canBeOrExtend(BuiltinTypes.TUPLE) ||
      !secondElement.type().canBeOrExtend(BuiltinTypes.DICT)) {
      ctx.addIssue(firstElement.firstToken(), secondElement.lastToken(), INVALID_GETNEWARGSEX_TUPLE_MESSAGE);
    }
  }

  private boolean isDatasetLenNoncompliant(ReturnStatement returnStatement) {
    if (!isEnclosingClassExtendingDataset(returnStatement)) {
      return false;
    }

    var returnExpression = returnStatement.expressions().get(0);
    return isShape(returnExpression);
  }

  private boolean isEnclosingClassExtendingDataset(Tree tree) {
    ClassDef enclosingClass = getEnclosingClass(tree);
    return enclosingClass != null && isTorchDataSetTypeCheck.check(enclosingClass.name().typeV2()).isTrue();
  }

  @CheckForNull
  private static ClassDef getEnclosingClass(Tree tree) {
    Tree functionDef = TreeUtils.firstAncestorOfKind(tree, Tree.Kind.FUNCDEF);

    if (functionDef == null) {
      return null;
    }

    return TreeUtils.firstAncestorOfClass(functionDef, ClassDef.class);
  }

  private static boolean isShape(Expression expr) {
    return expr instanceof QualifiedExpression qualifiedExpression && "shape".equals(qualifiedExpression.name().name());
  }

}

package org.sonar.python.checks.cdk;

import java.util.List;
import java.util.Optional;
import java.util.function.BiConsumer;
import org.sonar.check.Rule;
import org.sonar.plugins.python.api.SubscriptionContext;
import org.sonar.plugins.python.api.symbols.Symbol;
import org.sonar.plugins.python.api.tree.CallExpression;
import org.sonar.plugins.python.api.tree.ImportFrom;
import org.sonar.plugins.python.api.tree.Name;
import org.sonar.plugins.python.api.tree.QualifiedExpression;
import org.sonar.plugins.python.api.tree.Tree;

import static org.sonar.python.checks.cdk.CdkUtils.getArgument;

@Rule(key = "S6265")
public class S3BucketGrantedAccessCheck extends AbstractS3BucketCheck {

  public static final String MESSAGE_POLICY = "Make sure granting %s access is safe here.";
  public static final String MESSAGE_GRANT = "Make sure allowing unrestricted access to objects from this bucket is safe here.";
  private static final String S3_BUCKET_DEPLOYMENT_FQN = "aws_cdk.aws_s3_deployment.BucketDeployment";
  private static final String S3_BUCKET_AUTHENTICATED_READ = "aws_cdk.aws_s3.BucketAccessControl.AUTHENTICATED_READ";
  private static final String S3_BUCKET_PUBLIC_READ = "aws_cdk.aws_s3.BucketAccessControl.PUBLIC_READ";
  private static final String S3_BUCKET_PUBLIC_READ_WRITE = "aws_cdk.aws_s3.BucketAccessControl.PUBLIC_READ_WRITE";
  private static final List<String> S3_BUCKET_FQNS = List.of(S3_BUCKET_FQN, S3_BUCKET_DEPLOYMENT_FQN);
  private static final List<String> S3_BUCKET_SENSITIVE_POLICIES = List.of(S3_BUCKET_AUTHENTICATED_READ, S3_BUCKET_PUBLIC_READ, S3_BUCKET_PUBLIC_READ_WRITE);

  private boolean isAwsCdkImported = false;

  @Override
  public void initialize(Context context) {
    super.initialize(context);
    context.registerSyntaxNodeConsumer(Tree.Kind.FILE_INPUT, ctx -> isAwsCdkImported = false);
    context.registerSyntaxNodeConsumer(Tree.Kind.IMPORT_FROM, this::checkAWSImport);
  }

  private void checkAWSImport(SubscriptionContext ctx) {
    ImportFrom imports = (ImportFrom) ctx.syntaxNode();
    Optional.ofNullable(imports.module())
      .filter(dottedName -> dottedName.names()
        .stream()
        .map(Name::name)
        .anyMatch("aws_cdk"::equals))
      .ifPresent(n -> isAwsCdkImported = true);
  }

  @Override
  protected void visitNode(SubscriptionContext ctx) {
    CallExpression node = (CallExpression) ctx.syntaxNode();
    Optional<Symbol> symbol = Optional.ofNullable(node.calleeSymbol());

    symbol
      .map(Symbol::fullyQualifiedName)
      .filter(S3_BUCKET_FQNS::contains)
      .ifPresent(s -> visitBucketConstructor().accept(ctx, node));

    if (isAwsCdkImported) {
      symbol
        .map(Symbol::name)
        .filter("grant_public_access"::equals)
        .ifPresent(s -> ctx.addIssue(node.callee(), MESSAGE_GRANT));
    }
  }

  @Override
  BiConsumer<SubscriptionContext, CallExpression> visitBucketConstructor() {
    return (ctx, bucket) -> getArgument(ctx, bucket, "access_control")
      .ifPresent(argument -> argument.addIssueIf(CdkPredicate.isFqnOf(S3_BUCKET_SENSITIVE_POLICIES), getSensitivePolicyMessage(argument)));
  }

  private static String getSensitivePolicyMessage(CdkUtils.ExpressionFlow flow){
    String attribute = ((QualifiedExpression) flow.locations().getLast()).name().name();
    return String.format(MESSAGE_POLICY, attribute);
  }

}

package org.sonar.python.checks.cdk;

import java.util.Collections;
import java.util.Optional;
import java.util.function.BiConsumer;
import java.util.function.Predicate;
