    context.registerSyntaxNodeConsumer(ASSIGNMENT_STMT, CorsCheck::checkAllowOriginProperty);
    context.registerSyntaxNodeConsumer(CALL_EXPR, CorsCheck::checkDjangoResponseSetItem);

